// Narrow-only stub of get-east-asian-width for the r19 oracle. Returns the
// terminal cell width per code point: 2 for the standard EAW W/F ranges,
// 1 otherwise (ambiguous characters count 1, matching the package default).
// All r19 oracle scenario content is ASCII or ambiguous-width symbols, where
// this matches the real package.
const WIDE_RANGES = [
	[0x1100, 0x115f],
	[0x2e80, 0x303e],
	[0x3041, 0x33ff],
	[0x3400, 0x4dbf],
	[0x4e00, 0x9fff],
	[0xa000, 0xa4cf],
	[0xa960, 0xa97f],
	[0xac00, 0xd7a3],
	[0xf900, 0xfaff],
	[0xfe10, 0xfe19],
	[0xfe30, 0xfe6f],
	[0xff00, 0xff60],
	[0xffe0, 0xffe6],
	[0x1f300, 0x1f64f],
	[0x1f900, 0x1f9ff],
	[0x20000, 0x2fffd],
	[0x30000, 0x3fffd],
];

export function eastAsianWidth(codePoint) {
	for (const [lo, hi] of WIDE_RANGES) {
		if (codePoint >= lo && codePoint <= hi) return 2;
	}
	return 1;
}
